(64436, 1815, 327, '<td valign="top">Very cool. Love the colors and the light. Nice job.</td>', 'Very cool. Love the colors and the light. Nice job.', '2002-05-27 17:18:00.000000', NULL, 1),
(64437, 1815, 1061, '<td valign="top">Apt title</td>', 'Apt title', '2002-05-27 21:29:00.000000', NULL, 1),
(64438, 1815, 1750, '<td valign="top">Love the colored lights. The silhouette works here. The beer adds color to the story.</td>', 'Love the colored lights. The silhouette works here. The beer adds color to the story.', '2002-05-28 02:12:00.000000', NULL, 1),
(64439, 1815, 772, '<td valign="top">Nice shot!  I would like this one even more without the bottle :)<br/></td>', 'Nice shot!  I would like this one even more without the bottle :)', '2002-05-28 05:59:00.000000', NULL, 1),
(64440, 1815, 1005, '<td valign="top">Cool effect, very sixties....Could have lived  without the figures and florecent light on the left side.  A cleaner background would have helped this shot lots.  The subject is of course too dark, (I know, by design), but as a people shot, it leaves something....And you could have lived without the beer, totally unhelpful.<br/>Photo 7 Creativity 10 People 5 total 7 (I would have gone 9 w/o the distractions; beer, flor. light and cleaner background)</td>', 'Cool effect, very sixties....Could have lived  without the figures and florecent light on the left side.  A cleaner background would have helped this shot lots.  The subject is of course too dark, (I know, by design), but as a people shot, it leaves something....And you could have lived without the beer, totally unhelpful.Photo 7 Creativity 10 People 5 total 7 (I would have gone 9 w/o the distractions; beer, flor. light and cleaner background)', '2002-05-28 15:41:00.000000', NULL, 1),
(64441, 1815, 773, '<td valign="top">I really like the color diffusion behind the person, but the bottle seems to be more of the focus of the shot than the person.</td>', 'I really like the color diffusion behind the person, but the bottle seems to be more of the focus of the shot than the person.', '2002-05-28 16:02:00.000000', NULL, 1),
(64442, 1815, 1009, '<td valign="top">Cool effect...</td>', 'Cool effect...', '2002-05-29 18:07:00.000000', NULL, 1),
(64443, 1815, 301, '<td valign="top">Might be my monitor, but I had to take the photo into Photoshop and turn the brightness right up before realising that he was cross-eyed.  Probably one that needed fill-in flash</td>', 'Might be my monitor, but I had to take the photo into Photoshop and turn the brightness right up before realising that he was cross-eyed.  Probably one that needed fill-in flash', '2002-05-30 07:21:00.000000', NULL, 1),
(64444, 1815, 543, '<td valign="top">May being offered a beer at a party be your worst "nigthmare".  The lighing effects are cool, very cool, but there isn''t anything to hold my interest.</td>', 'May being offered a beer at a party be your worst "nigthmare".  The lighing effects are cool, very cool, but there isn''t anything to hold my interest.', '2002-05-31 13:34:00.000000', NULL, 1),
(64445, 1815, 1031, '<td valign="top">No thanks, I think I''ll just go home now and drink some distilled water...</td>', 'No thanks, I think I''ll just go home now and drink some distilled water...', '2002-06-01 23:18:00.000000', NULL, 1),
(64446, 1815, 1, '<td valign="top">Quite the interesting shot, the lights in the background work great to set the setting.  The look in his eyes and on his face (though dark) are great.</td>', 'Quite the interesting shot, the lights in the background work great to set the setting.  The look in his eyes and on his face (though dark) are great.', '2002-06-02 21:22:00.000000', NULL, 1),
(64447, 1818, 1750, '<td valign="top">Now I bet these guys are like this all the time -- NOT. Nice touchy feely moment with contrasting colors. Great skin tones. Framing is nice and tight on subjects.</td>', 'Now I bet these guys are like this all the time -- NOT. Nice touchy feely moment with contrasting colors. Great skin tones. Framing is nice and tight on subjects.', '2002-05-27 02:36:00.000000', NULL, 1),
