(64634, 1837, 1336, '<td valign="top">out of focus</td>', 'out of focus', '2002-06-02 22:21:00.000000', NULL, 1),
(64635, 1838, 1379, '<td valign="top">Nice set-up!  I love the "O Brother" poster in teh background...  This guy''s pose is so familiar and authentic.  I''m glad he let you snap him!</td>', 'Nice set-up!  I love the "O Brother" poster in teh background...  This guy''s pose is so familiar and authentic.  I''m glad he let you snap him!', '2002-05-27 11:22:00.000000', NULL, 1),
(64636, 1838, 661, '<td valign="top">I think this would have been better from a lower angle (more direct) with less background.  The sock feet and shoe on the floor add a personal touch though.</td>', 'I think this would have been better from a lower angle (more direct) with less background.  The sock feet and shoe on the floor add a personal touch though.', '2002-05-27 12:51:00.000000', NULL, 1),
(64637, 1838, 668, '<td valign="top">nice red</td>', 'nice red', '2002-05-27 10:55:00.000000', NULL, 1),
(64638, 1838, 327, '<td valign="top">Nice shot, love the mood and feeling. Good work.</td>', 'Nice shot, love the mood and feeling. Good work.', '2002-05-27 19:49:00.000000', NULL, 1),
(64639, 1838, 772, '<td valign="top">Rock on!</td>', 'Rock on!', '2002-05-27 20:55:00.000000', NULL, 1),
(64640, 1838, 907, '<td valign="top">would like to have seen this cropped tighter, no shoes, door frame, the complete foot pedals(?), and white pouch draws my eyes to it.  Other wise I do like this, it does catch the ''jammin'' feeling ... I don''t even know what is going on around me, I''m playing my guitar!</td>', 'would like to have seen this cropped tighter, no shoes, door frame, the complete foot pedals(?), and white pouch draws my eyes to it.  Other wise I do like this, it does catch the ''jammin'' feeling ... I don''t even know what is going on around me, I''m playing my guitar!', '2002-05-28 11:22:00.000000', NULL, 1),
(64641, 1838, 1005, '<td valign="top">Try to even up your background so the flash fills evenly, see how dark the left side is?  Try a lower camera angle, looking upwards into his face more.  The background is a bit cluttered, distracts from your subject.<br/>Photo 8 Creativity 7 People 8 total 8</td>', 'Try to even up your background so the flash fills evenly, see how dark the left side is?  Try a lower camera angle, looking upwards into his face more.  The background is a bit cluttered, distracts from your subject.Photo 8 Creativity 7 People 8 total 8', '2002-05-29 14:36:00.000000', NULL, 1),
(64642, 1838, 1907, '<td valign="top">love the posters/socks</td>', 'love the posters/socks', '2002-05-30 01:59:00.000000', NULL, 1),
(64643, 1838, 1, '<td valign="top">The flash or lighting you used didn''t really fill the left side of the photograph.</td>', 'The flash or lighting you used didn''t really fill the left side of the photograph.', '2002-05-30 22:05:00.000000', NULL, 1),
