(64645, 1839, 47, '<td valign="top">..lice ? how is that title in any way related to the content of the photograph? also, that fixture on the wall shouldnt be in the shot.</td>', '..lice ? how is that title in any way related to the content of the photograph? also, that fixture on the wall shouldnt be in the shot.', '2002-05-27 10:03:00.000000', NULL, 1),
