(64763, 1847, 907, '<td valign="top">Now THIS is a family portrait! LOL this is my kind of humor, love it, wish her whold veil and his hands made it in the photo, but like it anyway!</td>', 'Now THIS is a family portrait! LOL this is my kind of humor, love it, wish her whold veil and his hands made it in the photo, but like it anyway!', '2002-05-28 11:29:00.000000', NULL, 1),
(64764, 1847, 1005, '<td valign="top">Lippy!  Flash glare on glasses, otherwise pretty good shot!  (gripe about the background, but probably couldn''t be helped, no downgrade)<br/>Photo 9 Creativity 6 People 8 total 7</td>', 'Lippy!  Flash glare on glasses, otherwise pretty good shot!  (gripe about the background, but probably couldn''t be helped, no downgrade)Photo 9 Creativity 6 People 8 total 7', '2002-05-28 15:00:00.000000', NULL, 1),
(64765, 1847, 2, '<td valign="top">The humor of this shot really exemplifies the emotion you can capture with a "People" challenge, so good job on that.  The flash is pretty harsh.  I think I''d really have liked this one better if it were shot as a (or made to look like a) candid shot, rather than a posed one.</td>', 'The humor of this shot really exemplifies the emotion you can capture with a "People" challenge, so good job on that.  The flash is pretty harsh.  I think I''d really have liked this one better if it were shot as a (or made to look like a) candid shot, rather than a posed one.', '2002-05-28 15:18:00.000000', NULL, 1),
(64766, 1847, 1, '<td valign="top">Pretty funny, seems very snap shotty though.  I''d crop more tightly the focal point of the picture (their faces).</td>', 'Pretty funny, seems very snap shotty though.  I''d crop more tightly the focal point of the picture (their faces).', '2002-05-28 13:28:00.000000', NULL, 1),
(64767, 1847, 1379, '<td valign="top">This photo is so weird!  Are those wax lips?  Or are they making funny faces?  Or......  are they really so ..... special?<br/>I''m laughing!</td>', 'This photo is so weird!  Are those wax lips?  Or are they making funny faces?  Or......  are they really so ..... special?I''m laughing!', '2002-05-28 18:20:00.000000', NULL, 1),
(64768, 1847, 885, '<td valign="top">I''d love this picture if those were my relatives.  But the flash is a bit harsh and the color seems a bit off.</td>', 'I''d love this picture if those were my relatives.  But the flash is a bit harsh and the color seems a bit off.', '2002-05-29 15:13:00.000000', NULL, 1),
(64769, 1847, 587, '<td valign="top">This is hysterical. My kind of humor. :) The glare in glasses is always a pain (I wear them) If the person tips their head down slightly it can aleviate the problem, given enough time and a small screwdriver - remove the lenses from the glasses, or if they don''t mind just have them take the glasses off (watch out for marks on the nose from where they were sitting on the face)  The background is less than desireable (but this is always my problem too - never think about it) and if her headpiece and his hands were in it would have been perfect :) But without all the knitpicky things it is still a great photo - good job!</td>', 'This is hysterical. My kind of humor. :) The glare in glasses is always a pain (I wear them) If the person tips their head down slightly it can aleviate the problem, given enough time and a small screwdriver - remove the lenses from the glasses, or if they don''t mind just have them take the glasses off (watch out for marks on the nose from where they were sitting on the face)  The background is less than desireable (but this is always my problem too - never think about it) and if her headpiece and his hands were in it would have been perfect :) But without all the knitpicky things it is still a great photo - good job!', '2002-05-29 10:37:00.000000', NULL, 1),
(64770, 1847, 1599, '<td valign="top">this is too funny</td>', 'this is too funny', '2002-05-29 15:21:00.000000', NULL, 1),
(64771, 1847, 1031, '<td valign="top">Now, now, I bet if he wore white too they''d both look lovely...</td>', 'Now, now, I bet if he wore white too they''d both look lovely...', '2002-06-01 22:50:00.000000', NULL, 1),
(64772, 1847, 142, '<td valign="top">Funny and well done.</td>', 'Funny and well done.', '2002-06-01 23:05:00.000000', NULL, 1),
(64773, 1848, 661, '<td valign="top">Been there.  Don''t want to again.  To bad the "villian" wasn''t looking at the police officer.</td>', 'Been there.  Don''t want to again.  To bad the "villian" wasn''t looking at the police officer.', '2002-05-27 12:52:00.000000', NULL, 1),
(64774, 1848, 1750, '<td valign="top">Good use of color &amp;  reflection. Interested passerby adds authenticity, completes story. Dark car interior helps emphasize your subject.</td>', 'Good use of color &  reflection. Interested passerby adds authenticity, completes story. Dark car interior helps emphasize your subject.', '2002-05-27 02:33:00.000000', NULL, 1),
(64775, 1848, 1808, '<td valign="top">Very hard to make out face inside car.</td>', 'Very hard to make out face inside car.', '2002-05-27 10:15:00.000000', NULL, 1),
(64776, 1848, 327, '<td valign="top">Clean, clear shot with good color and _people_. You cut the top of their heads off, minus for the composition but this is over all a nice photo. Good work.</td>', 'Clean, clear shot with good color and _people_. You cut the top of their heads off, minus for the composition but this is over all a nice photo. Good work.', '2002-05-27 20:03:00.000000', NULL, 1),
(64777, 1848, 1878, '<td valign="top">Humorous!</td>', 'Humorous!', '2002-05-27 21:41:00.000000', NULL, 1),
(64778, 1848, 1061, '<td valign="top">When did Manson get paroled?</td>', 'When did Manson get paroled?', '2002-05-27 22:04:00.000000', NULL, 1),
(64779, 1848, 772, '<td valign="top">I hate it when this happens :)</td>', 'I hate it when this happens :)', '2002-05-27 22:14:00.000000', NULL, 1),
(64780, 1848, 301, '<td valign="top">Don''t know whether you could have waited for the guy in the background to walk past, cos he is distracting to the overall photo ... then again, the sign there is pretty distracting anyway.  I wouldn''t have cropped the policeman''s helmet</td>', 'Don''t know whether you could have waited for the guy in the background to walk past, cos he is distracting to the overall photo ... then again, the sign there is pretty distracting anyway.  I wouldn''t have cropped the policeman''s helmet', '2002-05-28 08:00:00.000000', NULL, 1),
(64781, 1848, 975, '<td valign="top">Tells a good story, if you can say a story about the San Francisco police is good!</td>', 'Tells a good story, if you can say a story about the San Francisco police is good!', '2002-05-28 11:16:00.000000', NULL, 1),
(64782, 1848, 1680, '<td valign="top">great snapshot, i would have liked too seen the focus of the picture on the old guy in the background with the cop and driver in slightly less focus</td>', 'great snapshot, i would have liked too seen the focus of the picture on the old guy in the background with the cop and driver in slightly less focus', '2002-05-28 12:04:00.000000', NULL, 1),
(64783, 1848, 1446, '<td valign="top">Man I hate it when this happens. Changing the dof and making the background less important in the photograph would have made me like it better.</td>', 'Man I hate it when this happens. Changing the dof and making the background less important in the photograph would have made me like it better.', '2002-05-28 14:15:00.000000', NULL, 1),
(64784, 1848, 1005, '<td valign="top">Oops!  No officer that''s not alcohol on my breath, I work in a BEER factory!  Victim is way dark, but this was a photo of opportunity, minus a little.  <br/>Photo 8 Creativity 8 People 8 total 8</td>', 'Oops!  No officer that''s not alcohol on my breath, I work in a BEER factory!  Victim is way dark, but this was a photo of opportunity, minus a little.  Photo 8 Creativity 8 People 8 total 8', '2002-05-28 18:18:00.000000', NULL, 1),
(64785, 1848, 1009, '<td valign="top">Hehe... busted.</td>', 'Hehe... busted.', '2002-05-29 18:05:00.000000', NULL, 1),
(64786, 1848, 1910, '<td valign="top">Wow!  Nice timing on the shot!</td>', 'Wow!  Nice timing on the shot!', '2002-05-30 03:09:00.000000', NULL, 1),
(64787, 1848, 1911, '<td valign="top">What an oppurtunity shot!</td>', 'What an oppurtunity shot!', '2002-05-30 03:22:00.000000', NULL, 1),
(64788, 1848, 1175, '<td valign="top">Framing is not good.  Move the camera about 1/4 of the way to the left and remove the space from behind the police officer.  This space does nothing for the picture.  Space in front of the police officer and driver do.  Look up Rule of Thirds.</td>', 'Framing is not good.  Move the camera about 1/4 of the way to the left and remove the space from behind the police officer.  This space does nothing for the picture.  Space in front of the police officer and driver do.  Look up Rule of Thirds.', '2002-05-31 12:58:00.000000', NULL, 1),
(64789, 1848, 811, '<td valign="top">Bad day.  At least the driver doesn''t look too upset.  Good focus and capture of light.  Background makes it look like a snapshot, obviously you couldn''t do a lot about that.</td>', 'Bad day.  At least the driver doesn''t look too upset.  Good focus and capture of light.  Background makes it look like a snapshot, obviously you couldn''t do a lot about that.', '2002-05-31 15:41:00.000000', NULL, 1),
(64790, 1848, 1031, '<td valign="top">Uh, be careful. The way things are going these days, taking a picture like this could get YOU arrested...</td>', 'Uh, be careful. The way things are going these days, taking a picture like this could get YOU arrested...', '2002-06-01 20:08:00.000000', NULL, 1),
(64791, 1848, 142, '<td valign="top">Talk about good photo ops!  I am sure this guy isn''t as happy about this as you were though!</td>', 'Talk about good photo ops!  I am sure this guy isn''t as happy about this as you were though!', '2002-06-01 23:07:00.000000', NULL, 1),
(64792, 1848, 637, '<td valign="top">Good catch</td>', 'Good catch', '2002-06-02 12:01:00.000000', NULL, 1),
(64793, 1849, 1379, '<td valign="top">You are so sneaky!  I like how you also got the decapitated bull in the background.</td>', 'You are so sneaky!  I like how you also got the decapitated bull in the background.', '2002-05-27 11:23:00.000000', NULL, 1),
(64794, 1849, 1175, '<td valign="top">Its an interesting photo.  I want more though.  Some sort of expression, some sort of action, some more color.  I''m more interested in the cow on the wall then the subject of your photo.</td>', 'Its an interesting photo.  I want more though.  Some sort of expression, some sort of action, some more color.  I''m more interested in the cow on the wall then the subject of your photo.', '2002-05-27 11:47:00.000000', NULL, 1),
(64795, 1849, 327, '<td valign="top">She a people alright. Nice work. I like the perspective.</td>', 'She a people alright. Nice work. I like the perspective.', '2002-05-27 16:46:00.000000', NULL, 1),
(64796, 1849, 1877, '<td valign="top">I have a few of these pics.. they''re fun but nothing terribly special. (sorry!!)</td>', 'I have a few of these pics.. they''re fun but nothing terribly special. (sorry!!)', '2002-05-27 19:35:00.000000', NULL, 1),
(64797, 1849, 1882, '<td valign="top">Is there supposed to be something creative here???</td>', 'Is there supposed to be something creative here???', '2002-05-28 08:57:00.000000', NULL, 1),
(64798, 1849, 772, '<td valign="top">Interesting shot and the green glow on her hair is neat too :)</td>', 'Interesting shot and the green glow on her hair is neat too :)', '2002-05-28 09:18:00.000000', NULL, 1),
(64799, 1849, 1037, '<td valign="top">The colourful lighting is really nice in this. I like the way you caught her face and hands in such a thoughtful expression. Her face has great texture and realness. I like this one a lot.</td>', 'The colourful lighting is really nice in this. I like the way you caught her face and hands in such a thoughtful expression. Her face has great texture and realness. I like this one a lot.', '2002-05-28 10:56:00.000000', NULL, 1),
(64800, 1849, 301, '<td valign="top">I actually quite like this photo.  Taken from a good angle, and the subject''s expression says so many things.  Portrait rather than landscape may have gotten rid of the bull head, neon sign and vents in the background.  Lighting isn''t brilliant ... especially the green from the right<br/></td>', 'I actually quite like this photo.  Taken from a good angle, and the subject''s expression says so many things.  Portrait rather than landscape may have gotten rid of the bull head, neon sign and vents in the background.  Lighting isn''t brilliant ... especially the green from the right', '2002-05-28 11:06:00.000000', NULL, 1),
(64801, 1849, 806, '<td valign="top">Good photojournalism-type shot. I''m not sure about the reds - but maybe that''s a reflection of the lights in the bar??? I really like it.</td>', 'Good photojournalism-type shot. I''m not sure about the reds - but maybe that''s a reflection of the lights in the bar??? I really like it.', '2002-05-28 17:29:00.000000', NULL, 1),
(64802, 1849, 737, '<td valign="top">She looks too placid for the title. Interesting lighting from top right.</td>', 'She looks too placid for the title. Interesting lighting from top right.', '2002-05-28 17:53:00.000000', NULL, 1),
(64803, 1849, 689, '<td valign="top">The tint is a a little off ... but that could possibly be the lighting ... would have been better if it had been tilted up slightly to give less emphasis to the glass and more to the lady.</td>', 'The tint is a a little off ... but that could possibly be the lighting ... would have been better if it had been tilted up slightly to give less emphasis to the glass and more to the lady.', '2002-05-28 18:03:00.000000', NULL, 1),
(64804, 1849, 1005, '<td valign="top">Don''t you just hate it when people won''t co-operate.  This is why I don''t like "people" photography.  Skin color makes the face appear somewhat grainy, but focus appears good.<br/>Photo 7 Creativity 7 People 8 total 7 <br/>(New rule:  if somebody doesn''t want their photo taken, scr#w ''em and make somebody else famous.  ; )</td>', 'Don''t you just hate it when people won''t co-operate.  This is why I don''t like "people" photography.  Skin color makes the face appear somewhat grainy, but focus appears good.Photo 7 Creativity 7 People 8 total 7 (New rule:  if somebody doesn''t want their photo taken, scr#w ''em and make somebody else famous.  ; )', '2002-05-29 15:14:00.000000', NULL, 1),
(64805, 1849, 1031, '<td valign="top">How sneaky...</td>', 'How sneaky...', '2002-05-30 22:58:00.000000', NULL, 1),
(64806, 1849, 811, '<td valign="top">What''s also amusing is the cow/buffalo/bull looks like it is looking at the camera as well.  If you can adjust white balance, you might want to try that, her skin has a reddish look to it (or she could just be really sunburned).</td>', 'What''s also amusing is the cow/buffalo/bull looks like it is looking at the camera as well.  If you can adjust white balance, you might want to try that, her skin has a reddish look to it (or she could just be really sunburned).', '2002-06-01 22:44:00.000000', NULL, 1),
(64807, 1849, 1, '<td valign="top">Even from this awkward angle, her eyes are very engaging.  I think the white balance could''ve been altered to make the colors look a little more appealing.</td>', 'Even from this awkward angle, her eyes are very engaging.  I think the white balance could''ve been altered to make the colors look a little more appealing.', '2002-06-02 21:42:00.000000', NULL, 1),
(64808, 1850, 1379, '<td valign="top">That HUGE hat is great!  I also like his little friend resting comfortably in the hay.  So authentic.</td>', 'That HUGE hat is great!  I also like his little friend resting comfortably in the hay.  So authentic.', '2002-05-27 11:31:00.000000', NULL, 1),
(64809, 1850, 616, '<td valign="top">I think this would have been a bit better if the kid in the hat was the single subject of the picture.</td>', 'I think this would have been a bit better if the kid in the hat was the single subject of the picture.', '2002-05-27 10:22:00.000000', NULL, 1),
(64810, 1850, 661, '<td valign="top">Nice Composition.  Great use of color!</td>', 'Nice Composition.  Great use of color!', '2002-05-27 13:12:00.000000', NULL, 1),
(64811, 1850, 509, '<td valign="top">Very nice picture, I wish the second boy on the left wasn''t cropped halfway out.  I think it would have been better with him either completely in or completely out of the frame</td>', 'Very nice picture, I wish the second boy on the left wasn''t cropped halfway out.  I think it would have been better with him either completely in or completely out of the frame', '2002-05-27 15:07:00.000000', NULL, 1),
(64812, 1850, 327, '<td valign="top">Darling shot. Maybe a little OOF or over sharpened. Still just cute and a good add for TEXAS!</td>', 'Darling shot. Maybe a little OOF or over sharpened. Still just cute and a good add for TEXAS!', '2002-05-27 16:38:00.000000', NULL, 1),
(64813, 1850, 686, '<td valign="top">I would have given this picture a higher score if the boy with the hat had been cropped.</td>', 'I would have given this picture a higher score if the boy with the hat had been cropped.', '2002-05-27 18:45:00.000000', NULL, 1),
(64814, 1850, 656, '<td valign="top">think I''d prefer it just with the one kid, rather than the two - would stand out more.  Like the texan outfit...</td>', 'think I''d prefer it just with the one kid, rather than the two - would stand out more.  Like the texan outfit...', '2002-05-28 10:01:00.000000', NULL, 1),
(64815, 1850, 772, '<td valign="top">Excellent shot!  I almost think that I would rather just see the boy with the hat in this photo... good job!</td>', 'Excellent shot!  I almost think that I would rather just see the boy with the hat in this photo... good job!', '2002-05-28 10:42:00.000000', NULL, 1),
(64816, 1850, 689, '<td valign="top">Try getting on the level of your subject or even lower ...</td>', 'Try getting on the level of your subject or even lower ...', '2002-05-28 18:05:00.000000', NULL, 1),
(64817, 1850, 332, '<td valign="top">Seeing at least one face would make it a better shot.</td>', 'Seeing at least one face would make it a better shot.', '2002-05-28 20:11:00.000000', NULL, 1),
(64818, 1850, 1005, '<td valign="top">Cute, good focus, great color, minor nit:  I would have liked to see something of a face, but oh well.....(or what they were staring at, as a reason why we don''t see their faces)<br/>Photo 9 Creativity 8 People 8 total 8</td>', 'Cute, good focus, great color, minor nit:  I would have liked to see something of a face, but oh well.....(or what they were staring at, as a reason why we don''t see their faces)Photo 9 Creativity 8 People 8 total 8', '2002-05-29 13:01:00.000000', NULL, 1),
(64819, 1850, 811, '<td valign="top">Either get more of the kid in blue, or crop him out.    this shot might have also been effective to have the "cowboy" in the center, but i know that may not have been possible.  Also, black and white would have given this a real feeling of nostalgia, I think.</td>', 'Either get more of the kid in blue, or crop him out.    this shot might have also been effective to have the "cowboy" in the center, but i know that may not have been possible.  Also, black and white would have given this a real feeling of nostalgia, I think.', '2002-05-29 13:24:00.000000', NULL, 1),
(64820, 1850, 1041, '<td valign="top">Now, I generally prefer to see faces in the "people" shots because they say so much about people, but this one''s an exception.  I really like the shot.  Two things that would''ve made this one perfect (and that may not have been possible, since I can''t see outside of the photo) is if the kid to the left wasn''t in the shot (could you have the boy standing up on the left of your shot and then include more of what''s to the right?).  For some reason I imagine he should be on tip-toes to try to look over the bar in the fence.</td>', 'Now, I generally prefer to see faces in the "people" shots because they say so much about people, but this one''s an exception.  I really like the shot.  Two things that would''ve made this one perfect (and that may not have been possible, since I can''t see outside of the photo) is if the kid to the left wasn''t in the shot (could you have the boy standing up on the left of your shot and then include more of what''s to the right?).  For some reason I imagine he should be on tip-toes to try to look over the bar in the fence.', '2002-05-29 14:16:00.000000', NULL, 1),
(64821, 1850, 1585, '<td valign="top">Don''t let your babys.... SIT ON THE GROUND AT THE RODEO!!!!!!!!</td>', 'Don''t let your babys.... SIT ON THE GROUND AT THE RODEO!!!!!!!!', '2002-05-29 18:25:00.000000', NULL, 1),
(64822, 1850, 1679, '<td valign="top">Nice saturated colours and a warm touch.It''s a pity though that the boy on the left is cut in half. :-(<br/>It would have made an even better shot.</td>', 'Nice saturated colours and a warm touch.It''s a pity though that the boy on the left is cut in half. :-(It would have made an even better shot.', '2002-05-29 18:47:00.000000', NULL, 1),
(64823, 1850, 301, '<td valign="top">Better composition would have made this a very fine photo.  Definitely getting rid of the boy in the blue t-shirt, and possibly centering the cowboy.  Might have been nice to see exactly what they were staring at too.</td>', 'Better composition would have made this a very fine photo.  Definitely getting rid of the boy in the blue t-shirt, and possibly centering the cowboy.  Might have been nice to see exactly what they were staring at too.', '2002-05-30 07:31:00.000000', NULL, 1),
(64824, 1850, 885, '<td valign="top">I love the fence, the hat, the shirt, and those boots are adorable.  I don''t know if you cropped.  If you had a choice, I don''t think I''d have chosen to include the other kid.</td>', 'I love the fence, the hat, the shirt, and those boots are adorable.  I don''t know if you cropped.  If you had a choice, I don''t think I''d have chosen to include the other kid.', '2002-05-30 20:05:00.000000', NULL, 1),
(64825, 1850, 2, '<td valign="top">I don''t like how the other kid is cropped in half in the framing of the shot, and the image seems slightly grainy... but the kid by himself with his bright shirt would be awesome.</td>', 'I don''t like how the other kid is cropped in half in the framing of the shot, and the image seems slightly grainy... but the kid by himself with his bright shirt would be awesome.', '2002-05-30 20:17:00.000000', NULL, 1),
(64826, 1855, 1867, '<td valign="top">beautious!</td>', 'beautious!', '2002-05-27 08:06:00.000000', NULL, 1),
(64827, 1855, 806, '<td valign="top">Well executed, but please crop out the distracting brighter window and shovel handle to the left. (edit) : Takes away from the picture, but still sweet.</td>', 'Well executed, but please crop out the distracting brighter window and shovel handle to the left. (edit) : Takes away from the picture, but still sweet.', '2002-05-27 09:00:00.000000', NULL, 1),
(64828, 1855, 1808, '<td valign="top">It''s happy. I like it. What''s that stick outside the window though?</td>', 'It''s happy. I like it. What''s that stick outside the window though?', '2002-05-27 10:07:00.000000', NULL, 1),
(64829, 1855, 668, '<td valign="top">too much of a birthday card</td>', 'too much of a birthday card', '2002-05-27 10:43:00.000000', NULL, 1),
(64830, 1855, 1211, '<td valign="top">Great shot, if only there was no screen on the window.  Still love it though.</td>', 'Great shot, if only there was no screen on the window.  Still love it though.', '2002-05-27 10:47:00.000000', NULL, 1),
(64831, 1855, 472, '<td valign="top">this is my favorite picture in this challenge. lighting, composition, and a lovely child, all excellent.  i dont really like that thing leaning on the glass, but hey cant have it all ..</td>', 'this is my favorite picture in this challenge. lighting, composition, and a lovely child, all excellent.  i dont really like that thing leaning on the glass, but hey cant have it all ..', '2002-05-27 14:57:00.000000', NULL, 1),
(64832, 1855, 509, '<td valign="top">Very nice.  I like the choice of black and white, as well as the soft focus.  An even softer one might even be better, but I for one don''t know how to do one = P  Nice work - 8</td>', 'Very nice.  I like the choice of black and white, as well as the soft focus.  An even softer one might even be better, but I for one don''t know how to do one = P  Nice work - 8', '2002-05-27 15:17:00.000000', NULL, 1),
(64833, 1855, 327, '<td valign="top">Love the younglady and the lighting, also the b&amp;w is very good. My only negitive is the chair out the window, it''s distracting. Over all this is a fine shot and her look is perfectly lovely. Good work.</td>', 'Love the younglady and the lighting, also the b&w is very good. My only negitive is the chair out the window, it''s distracting. Over all this is a fine shot and her look is perfectly lovely. Good work.', '2002-05-27 19:44:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
