(65676, 1905, 1750, '<td valign="top">Good detail in the hands; however it overpowers the soft focus on the face.</td>', 'Good detail in the hands; however it overpowers the soft focus on the face.', '2002-05-28 01:22:00.000000', NULL, 1),
(65677, 1905, 1041, '<td valign="top">Oh, what a precious photo this would be if only the face, instead of the hand was in focus!  To do this, frame the face in the middle, press the shutter release button half way down to hold the focus, then move your camera to recompose the picture.</td>', 'Oh, what a precious photo this would be if only the face, instead of the hand was in focus!  To do this, frame the face in the middle, press the shutter release button half way down to hold the focus, then move your camera to recompose the picture.', '2002-05-28 09:38:00.000000', NULL, 1),
(65678, 1905, 656, '<td valign="top">the hand looks quite out of place in this shot, perhaps moving more to the left would have helped, as it looks almost deformed because of being ''cut off'' by the blanket.</td>', 'the hand looks quite out of place in this shot, perhaps moving more to the left would have helped, as it looks almost deformed because of being ''cut off'' by the blanket.', '2002-05-28 09:53:00.000000', NULL, 1),
