(65750, 1908, 907, '<td valign="top">great sense of humor and creativity</td>', 'great sense of humor and creativity', '2002-05-28 11:37:00.000000', NULL, 1),
(65751, 1908, 1520, '<td valign="top">Too much glare on the "faces" though.  Might''ve tried taking a shot with the flash off or diffusing the lighting.  <br/><br/>The shadows beside the fingers are too strong.  Might''ve tried moving the hand away from the background, using no flash, or diffusing the lighting.<br/><br/>Might''ve chose a better background.  Something that a family might be standing in front of.  e.g. a church.<br/><br/>Extra points for creativity though.<br/></td>', 'Too much glare on the "faces" though.  Might''ve tried taking a shot with the flash off or diffusing the lighting.  The shadows beside the fingers are too strong.  Might''ve tried moving the hand away from the background, using no flash, or diffusing the lighting.Might''ve chose a better background.  Something that a family might be standing in front of.  e.g. a church.Extra points for creativity though.', '2002-05-28 12:03:00.000000', NULL, 1),
(65752, 1908, 1446, '<td valign="top">Close ups of hands should start with very well manicured hands IMO. Good color and focus.</td>', 'Close ups of hands should start with very well manicured hands IMO. Good color and focus.', '2002-05-28 13:38:00.000000', NULL, 1),
