(65815, 1912, 1865, '<td valign="top">Like the rain and the way the kid is caught unaware by the camera and the situation. Good shot.</td>', 'Like the rain and the way the kid is caught unaware by the camera and the situation. Good shot.', '2002-05-27 05:09:00.000000', NULL, 1),
