(65824, 1912, 1878, '<td valign="top">This picture goes very well with the topic.</td>', 'This picture goes very well with the topic.', '2002-05-27 21:26:00.000000', NULL, 1),
(65825, 1912, 773, '<td valign="top">I LOVE this shot!  Great capture of the hard rain and the feeling of the photo.</td>', 'I LOVE this shot!  Great capture of the hard rain and the feeling of the photo.', '2002-05-27 21:45:00.000000', NULL, 1),
(65826, 1912, 1820, '<td valign="top">Great photo!!</td>', 'Great photo!!', '2002-05-27 23:29:00.000000', NULL, 1),
(65827, 1912, 1446, '<td valign="top">I love this photograph!  How did you keep your lense dry?? I would not change a thing.  A perfect 10 in my book.</td>', 'I love this photograph!  How did you keep your lense dry?? I would not change a thing.  A perfect 10 in my book.', '2002-05-28 03:52:00.000000', NULL, 1),
(65828, 1912, 301, '<td valign="top">I generally not a fan of photos showing the backs of people, but this works well.  Beautifully done.  To be very picky (and this hasn''t affected my score), the ground betwen yourself and the boy seems quite dry in contrast to the rest ... I understand that you were protecting your camera, but if the boy did decided to keep going into the downpour, it would have been an even more powerful if you could have eliminated the dry ground.  Congrats on a great photo :)</td>', 'I generally not a fan of photos showing the backs of people, but this works well.  Beautifully done.  To be very picky (and this hasn''t affected my score), the ground betwen yourself and the boy seems quite dry in contrast to the rest ... I understand that you were protecting your camera, but if the boy did decided to keep going into the downpour, it would have been an even more powerful if you could have eliminated the dry ground.  Congrats on a great photo :)', '2002-05-28 09:04:00.000000', NULL, 1),
(65829, 1912, 656, '<td valign="top">great image, fun picture.</td>', 'great image, fun picture.', '2002-05-28 09:56:00.000000', NULL, 1),
(65830, 1912, 1041, '<td valign="top">Awesome shot.  You need to enter this into the rain competition on www.photoblink.com if you haven''t already!  Other than the strap of the umbrella (and even that is very nitpicky, and could be cloned out outside of dpchallenge), I have no suggestions for improvements.</td>', 'Awesome shot.  You need to enter this into the rain competition on www.photoblink.com if you haven''t already!  Other than the strap of the umbrella (and even that is very nitpicky, and could be cloned out outside of dpchallenge), I have no suggestions for improvements.', '2002-05-28 09:58:00.000000', NULL, 1),
