(65835, 1912, 1680, '<td valign="top">Awesome shot! I feel like im gonna get wet looking at it.</td>', 'Awesome shot! I feel like im gonna get wet looking at it.', '2002-05-28 12:12:00.000000', NULL, 1),
(65836, 1912, 1042, '<td valign="top">This is a great photo!!! That poor child..lol <br/>One of my 10''s :)</td>', 'This is a great photo!!! That poor child..lol One of my 10''s :)', '2002-05-28 14:18:00.000000', NULL, 1),
(65837, 1912, 1882, '<td valign="top">Absolutely adorable!  How long did you make the poor kid stand out in that downpour though?  Beautiful photograph!</td>', 'Absolutely adorable!  How long did you make the poor kid stand out in that downpour though?  Beautiful photograph!', '2002-05-28 14:56:00.000000', NULL, 1),
(65838, 1912, 772, '<td valign="top">This is a most excellent photograph... I LOVE IT!  Is this in a fountain or is it actual rain&amp;gt;  The water patterns on teh pavement seem like they are quite uneven... either way, you get a 10 this week for creativity and composition... Kudos!</td>', 'This is a most excellent photograph... I LOVE IT!  Is this in a fountain or is it actual rain&gt;  The water patterns on teh pavement seem like they are quite uneven... either way, you get a 10 this week for creativity and composition... Kudos!', '2002-05-28 15:13:00.000000', NULL, 1),
(65839, 1912, 281, '<td valign="top">Great shot!  Well composed</td>', 'Great shot!  Well composed', '2002-05-28 13:05:00.000000', NULL, 1),
(65840, 1912, 1674, '<td valign="top">excellent!</td>', 'excellent!', '2002-05-28 13:36:00.000000', NULL, 1),
(65841, 1912, 1, '<td valign="top">That''s quite a bit of rain!  I''d prefer to see the front of him instead of the back.  That or give some hint that he would be walking away.  Just standing doesn''t do much for me.  Otherwise you did a great job on the framing and chosen angle.</td>', 'That''s quite a bit of rain!  I''d prefer to see the front of him instead of the back.  That or give some hint that he would be walking away.  Just standing doesn''t do much for me.  Otherwise you did a great job on the framing and chosen angle.', '2002-05-28 13:39:00.000000', NULL, 1),
(65842, 1912, 1717, '<td valign="top">wonderful!  good focus...lovely colors...interesting subject.</td>', 'wonderful!  good focus...lovely colors...interesting subject.', '2002-05-28 14:00:00.000000', NULL, 1),
(65843, 1912, 255, '<td valign="top">great capture! love this.</td>', 'great capture! love this.', '2002-05-28 14:04:00.000000', NULL, 1),
(65844, 1912, 806, '<td valign="top">I love this!</td>', 'I love this!', '2002-05-28 17:13:00.000000', NULL, 1),
(65845, 1912, 1005, '<td valign="top">Wow, I like this one.  Doesn''t look like the umbrella was much help.  I don''t see anything I could suggest to improve this shot.  Well done!  Keep up the good work!<br/>Photo 10 Creativity 9 People 9 total 9</td>', 'Wow, I like this one.  Doesn''t look like the umbrella was much help.  I don''t see anything I could suggest to improve this shot.  Well done!  Keep up the good work!Photo 10 Creativity 9 People 9 total 9', '2002-05-28 17:33:00.000000', NULL, 1),
