(65856, 1912, 142, '<td valign="top">This is cute.  He looks like he is having the time of his life.  The water looks great cascading over the umbrella.</td>', 'This is cute.  He looks like he is having the time of his life.  The water looks great cascading over the umbrella.', '2002-05-29 18:23:00.000000', NULL, 1),
(65857, 1912, 1859, '<td valign="top">I absolutely love this photo</td>', 'I absolutely love this photo', '2002-05-29 20:06:00.000000', NULL, 1),
(65858, 1912, 1175, '<td valign="top">Forcing a little boy into the rain with a bad umbrella, shame on you. ;)  This is an excellent picture in my opinion.  I love how the boy is tilted to the left sort of scrunched over fighting the weight of the rain and and the coldness of the water.  10.</td>', 'Forcing a little boy into the rain with a bad umbrella, shame on you. ;)  This is an excellent picture in my opinion.  I love how the boy is tilted to the left sort of scrunched over fighting the weight of the rain and and the coldness of the water.  10.', '2002-05-30 07:07:00.000000', NULL, 1),
(65859, 1912, 1066, '<td valign="top">What can I say.  You know it''s good..I know its good.  10.......One of my 4 10''s this week.</td>', 'What can I say.  You know it''s good..I know its good.  10.......One of my 4 10''s this week.', '2002-05-30 09:12:00.000000', NULL, 1),
(65860, 1912, 573, '<td valign="top">But it looks to be too late.  I hope you didn''t make him get soaked just to take a picture.  Nice photograph.</td>', 'But it looks to be too late.  I hope you didn''t make him get soaked just to take a picture.  Nice photograph.', '2002-05-30 17:03:00.000000', NULL, 1),
