(66079, 1923, 312, '<td valign="top">beautiful. my second highest rating this challenge. parhaps a tad too dark, but i love the feeling the whole thing evokes. great shapes and shadows.</td>', 'beautiful. my second highest rating this challenge. parhaps a tad too dark, but i love the feeling the whole thing evokes. great shapes and shadows.', '2002-05-28 22:30:00.000000', NULL, 1),
