(66097, 1924, 1831, '<td valign="top">Looks like a poster. I like it</td>', 'Looks like a poster. I like it', '2002-05-27 02:34:00.000000', NULL, 1),
(66098, 1924, 1037, '<td valign="top">I''m sure this photo will polarise the voters. I''m one of those who loves it! Very striking. It creates a real atmosphere, and although the man is blurry, I think it''s in a good, line of action kind of way.</td>', 'I''m sure this photo will polarise the voters. I''m one of those who loves it! Very striking. It creates a real atmosphere, and although the man is blurry, I think it''s in a good, line of action kind of way.', '2002-05-27 04:00:00.000000', NULL, 1),
(66099, 1924, 1, '<td valign="top">The thumbnail promised to be an excellent shot, but the blur/focus problem bothers me.  So much potential.</td>', 'The thumbnail promised to be an excellent shot, but the blur/focus problem bothers me.  So much potential.', '2002-05-27 09:11:00.000000', NULL, 1),
(66100, 1924, 1808, '<td valign="top">Sort of a 70''s modern art feel. I like it.</td>', 'Sort of a 70''s modern art feel. I like it.', '2002-05-27 10:18:00.000000', NULL, 1),
(66101, 1924, 616, '<td valign="top">I love the technique used in this photo. The usage of a lot of space and the single subject is great. This is a technique I haven''t seen used in a while. I just wish the guy was focused.</td>', 'I love the technique used in this photo. The usage of a lot of space and the single subject is great. This is a technique I haven''t seen used in a while. I just wish the guy was focused.', '2002-05-27 10:19:00.000000', NULL, 1),
