(66572, 1946, 1061, '<td valign="top">I dunno, they seem mad at each other right now!</td>', 'I dunno, they seem mad at each other right now!', '2002-05-27 21:29:00.000000', NULL, 1),
(66573, 1946, 1750, '<td valign="top">What works here for me is the framing formed by both the tree and a pattern in the grass. It''s a bit dark though. I''d try to frame out the trash can on the head. Might even try a warmer tone paper.</td>', 'What works here for me is the framing formed by both the tree and a pattern in the grass. It''s a bit dark though. I''d try to frame out the trash can on the head. Might even try a warmer tone paper.', '2002-05-28 02:07:00.000000', NULL, 1),
(66574, 1946, 772, '<td valign="top">I like this photo, but I believe that it is a little on the dark side.  Maybe a fill flash or a little less brightness reduction would have been nicer :)</td>', 'I like this photo, but I believe that it is a little on the dark side.  Maybe a fill flash or a little less brightness reduction would have been nicer :)', '2002-05-28 05:57:00.000000', NULL, 1),
